nt(f\"i={i+1}: X_i={X_i}, X_i/X(k+1)={X_i/X_kplus1:.6f}, log={sum([(sorted_values[j]/X_kplus1) - 1 for j in range(i+1)]) if i > 0 else (sorted_values[0]/X_kplus1) - 1}\")\n    \n# Let me recalculate using the correct formula\n# Hill estimator: 1/alpha = (1/k) * sum_{i=1}^{k} log(X_(i)) - log(X_(k+1))\n# Or equivalently: alpha = k / sum_{i=1}^{k} log(X_(i) / X_(k+1))\n\nimport math\n\nlog_sum = 0\nfor i in range(k):\n    X_i = sorted_values[i]\n    log_ratio = math.log(X_i / X_kplus1)\n    log_sum += log_ratio\n    print(f\"i={i+1}: X_i={X_i}, log(X_i/X(k+1))={log_ratio:.6f}\")\n\nprint(f\"\\nSum of logs: {log_sum:.6f}\")\nalpha_hat = k / log_sum\nprint(f\"Hill estimator (alpha): {alpha_hat:.6f}\")\nprint(f\"Rounded to 3 decimal places: {alpha_hat:.3f}\")\n\n# Also let's verify with the alternative formula\n# 1/alpha = (1/k) * sum(log(X_i)) - log(X_(k+1))\nlog_sum2 = sum([math.log(sorted_values[i]) for i in range(k)])\nterm = (1/k) * log_sum2 - math.log(X_kplus1)\nalpha_hat2 = 1 / term\nprint(f\"\\nAlternative formula: {alpha_hat2:.6f}\")\n\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
